/** JDK process adapter with bounded execution and no inherited output. */
public final class SystemProcessRunner implements ProcessRunner {
    @Override
    public RunningProcess start(List<String> command) {
        try {
            Process process = new ProcessBuilder(command).redirectErrorStream(true)
                    .redirectOutput(ProcessBuilder.Redirect.DISCARD).start();
            return new RunningProcess() {
                @Override public boolean isAlive() { return process.isAlive(); }
                @Override public void close() {
                    process.destroy();
                    try {
                        if (!process.waitFor(2, TimeUnit.SECONDS)) {
                            process.destroyForcibly();
                            process.waitFor();
                        }
                    } catch (InterruptedException exception) {
                        Thread.currentThread().interrupt();
                        process.destroyForcibly();
                        throw new IllegalStateException("interrupted while closing SSH process", exception);
                    }
                }
            };
        } catch (IOException exception) {
            throw new IllegalStateException("cannot start SSH process", exception);
        }
    }

